async function run(wf, args) {
  const findings = await wf.phase("review", async () => await wf.parallel(args.scopes.map((scope, index) => async () => await wf.runAgent({ name: "reviewer-" + (index + 1), prompt: args.request + "\nScope: " + scope, scopeSummary: scope, readOnly: true, modelHint: "deep" })), { concurrency: 3 }));
  const verification = await wf.phase("verify", async () => await wf.runAgent({ name: "verifier", prompt: "Challenge and deduplicate these findings:\n" + JSON.stringify(findings), readOnly: true, modelHint: "deep" }));
  await wf.artifact("review-evidence", { findings, verification });
  return await wf.phase("synthesize", async () => await wf.synthesize({ inputs: [findings, verification], rubric: "Return only evidence-backed findings in severity order." }));
}
